 * never exceed it. No cap is applied when the owner had no existing household member at creation.
 */
@Named("formatMembershipLevel")
default Integer formatMembershipLevel(Owner owner) {
    Integer points = formatMembershipPoints(owner);
    if (points == null) {
        return null;
    }
    int level;
    if (points <= 1) {
        level = 1;
    }
    else if (points <= 3) {
        level = 2;
    }
    else if (points <= 5) {
        level = 3;
    }
    else {
        level = 4;
    }
    Integer cap = owner.getMembershipLevelCap();
    if (cap != null && level > cap) {
        level = cap;
    }
