/**
 * Whether more than 80 owners have already been created on {@code registrationDate},
 * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
 */
private boolean isBulkSignup(LocalDate registrationDate) {
    return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
}

/**
 * Computes the membership-level ceiling for a new owner joining the household identified by
 * {@code householdId}: one above the current maximum {@code membershipLevel} among the existing
 * (non-deleted) household members. Returns {@code null} when the household has no existing
 * member, so no cap applies to the new owner.
 */
private Integer computeMembershipLevelCap(String householdId) {
    Collection<Owner> members = this.clinicService.findOwnersByHouseholdId(householdId);
    if (members.isEmpty()) {
        return null;
    }
    int maxLevel = 0;
    for (Owner member : members) {
        member.setHouseholdSize(members.size());
        Integer level = this.ownerMapper.formatMembershipLevel(member);
        if (level != null && level > maxLevel) {
            maxLevel = level;
        }
    }
    return maxLevel + 1;
}

